package com.manggome.oneemu.library

import java.io.File
import java.io.InputStream
import java.util.zip.GZIPInputStream
import java.util.zip.ZipFile

/**
 * Arcade ROM doctor: compares a MAME zip against the reference set of one of the bundled MAME cores
 * (coreassets/<coreId>/romdb.tsv.gz, generated by cores/<coreId>/gen-romdb.py) and explains what is
 * missing. Pure JVM — no Android types — so it is unit-testable; [ArcadeRomChecker] adds the asset
 * loading, caching and Korean texts, [ArcadeCoreRouter] turns the result into a core choice.
 *
 * Matching follows MAME file loading: every file is looked up in the game zip, then up the `romof`
 * chain (parent zip, BIOS zip). A file is satisfied when an entry with the same CRC (and size) exists
 * anywhere in that chain; an entry with the right name but another CRC counts as a mismatch.
 *
 * [resolve] looks the zip up in several DBs (one per core, in preference order). When no DB knows the
 * file name it falls back to CRC identification: newer MAME versions renamed many sets (rbisland vs
 * rainbow, spidman vs spidey …), so the zip's entry CRCs are matched against every game's ROM list and
 * the best fit is reported as [Status.RENAME_SUGGESTED].
 */
object ArcadeRomCheck {
    enum class Status { OK, MISSING_FILES, WRONG_SET, NEEDS_PARENT, NEEDS_BIOS, NEEDS_SAMPLES, CHD_UNSUPPORTED, NOT_IN_DAT, RENAME_SUGGESTED }

    /** Badge colour class for the library list. */
    enum class Severity { OK, WARN, ERROR }

    data class Rom(
        val name: String,
        val size: Long,
        /** lowercase 8-hex CRC32 */
        val crc: String,
        /** null = the game's own file; "=" = same name in the romof set; else the file name in the romof set */
        val merge: String?,
        /** <biosset> name when this file belongs to one selectable BIOS; only one BIOS file is needed */
        val bios: String?,
    ) {
        val merged: Boolean get() = merge != null
        val mergeName: String get() = if (merge == null || merge == "=") name else merge
    }

    data class Game(
        val name: String,
        val description: String,
        val cloneof: String,
        val romof: String,
        /** BIOS set zip short name (e.g. "neogeo") or "" */
        val bios: String,
        val sampleof: String,
        val needsSamples: Boolean,
        val disks: Int,
        val runnable: Boolean,
        val roms: List<Rom>,
    ) {
        /** Files this set ships itself (not merged from a parent/BIOS, not BIOS alternatives). */
        val ownRoms: List<Rom> get() = roms.filter { !it.merged && it.bios == null }
    }

    class Db(private val games: Map<String, Game>) {
        val size: Int get() = games.size
        operator fun get(shortName: String): Game? = games[shortName.lowercase()]

        /** CRC → games listing a ROM with that CRC. Built on first CRC identification only (costs a few MB). */
        private val crcIndex: Map<String, List<Game>> by lazy {
            val map = HashMap<String, MutableList<Game>>(games.size * 8)
            for (g in games.values) for (r in g.roms) map.getOrPut(r.crc) { ArrayList(2) }.add(g)
            map
        }

        /**
         * Finds the game a zip with these entry CRCs most likely is. BIOS sets are never suggested. A game qualifies
         * when all of its own (non-merged) files are present, or when ≥ [minShare] of the zip's entries belong to it
         * and at least half of its own files are there (so one shared BIOS/parent CRC never matches everything).
         * Ties prefer a complete own-file set, more matches, a ROM count close to the zip's, parents over clones, then name.
         */
        fun identify(crcs: Set<String>, minShare: Double = 0.6): Game? {
            if (crcs.isEmpty()) return null
            val hits = HashMap<String, Int>()
            val byName = HashMap<String, Game>()
            for (crc in crcs) for (g in crcIndex[crc] ?: continue) {
                // Count distinct zip CRCs per game (a game may list the same CRC twice).
                hits[g.name] = (hits[g.name] ?: 0) + 1
                byName[g.name] = g
            }
            if (hits.isEmpty()) return null
            val need = kotlin.math.ceil(crcs.size * minShare).toInt().coerceAtLeast(1)
            data class Scored(val game: Game, val matched: Int, val ownShare: Double)
            val candidates = hits.mapNotNull { (name, matched) ->
                val g = byName[name] ?: return@mapNotNull null
                if (!g.runnable) return@mapNotNull null
                val own = g.ownRoms
                val ownMatched = own.count { it.crc in crcs }
                val ownShare = if (own.isEmpty()) 0.0 else ownMatched.toDouble() / own.size
                val complete = own.isNotEmpty() && ownMatched == own.size
                if (complete || (matched >= need && ownShare >= 0.5)) Scored(g, matched, ownShare) else null
            }
            return candidates.sortedWith(
                compareByDescending<Scored> { it.ownShare }
                    .thenByDescending { it.matched }
                    .thenBy { kotlin.math.abs(it.game.roms.size - crcs.size) }
                    .thenByDescending { it.game.cloneof.isEmpty() }
                    .thenBy { it.game.name },
            ).firstOrNull()?.game
        }

        companion object {
            fun parseGzip(input: InputStream): Db = parse(GZIPInputStream(input, 64 * 1024))

            fun parse(input: InputStream): Db {
                val map = HashMap<String, Game>(6000)
                input.bufferedReader(Charsets.UTF_8).useLines { lines ->
                    for (line in lines) {
                        if (line.isEmpty() || line[0] == '#') continue
                        parseLine(line)?.let { map[it.name.lowercase()] = it }
                    }
                }
                return Db(map)
            }

            /** name  description  cloneof  romof  bios  sampleof  needsSamples  disks  runnable  roms */
            fun parseLine(line: String): Game? {
                val p = line.split('\t')
                if (p.size < 10) return null
                val roms = if (p[9].isEmpty()) emptyList() else p[9].split(';').mapNotNull { tok ->
                    val f = tok.split(':')
                    if (f.size < 3) return@mapNotNull null
                    Rom(
                        name = unescape(f[0]),
                        size = f[1].toLongOrNull() ?: 0L,
                        crc = f[2].lowercase(),
                        merge = f.getOrNull(3)?.takeIf { it.isNotEmpty() }?.let { if (it == "=") it else unescape(it) },
                        bios = f.getOrNull(4)?.takeIf { it.isNotEmpty() }?.let(::unescape),
                    )
                }
                return Game(
                    name = p[0], description = p[1], cloneof = p[2], romof = p[3], bios = p[4], sampleof = p[5],
                    needsSamples = p[6] == "1", disks = p[7].toIntOrNull() ?: 0, runnable = p[8] != "0", roms = roms,
                )
            }

            private fun unescape(s: String): String =
                if ('%' !in s) s else s.replace("%3A", ":").replace("%3B", ";").replace("%25", "%")
        }
    }

    /** One file the set lacks ([foundCrc] == null) or has with the wrong content. */
    data class FileIssue(
        val name: String,
        val expectedCrc: String,
        val size: Long,
        val foundCrc: String?,
        /** Short name of the zip that should contain the file (the game itself, its parent or the BIOS set). */
        val owner: String,
    ) {
        val missing: Boolean get() = foundCrc == null
    }

    data class Report(
        /** The zip's file name (lowercase, no extension) — for RENAME_SUGGESTED this is the wrong/new name. */
        val shortName: String,
        val status: Status,
        val game: Game?,
        val issues: List<FileIssue> = emptyList(),
        /** Parent (split-set) zip short name, when the game is a clone. */
        val parentZip: String? = null,
        val parentPresent: Boolean = false,
        val biosZip: String? = null,
        val biosPresent: Boolean = false,
        val sampleZip: String? = null,
        val samplesPresent: Boolean = false,
        val disks: Int = 0,
        /** Set that is absent and owns missing files (NEEDS_PARENT / NEEDS_BIOS). */
        val neededZip: String? = null,
        /** RENAME_SUGGESTED: the DAT short name this zip should have (== game.name). */
        val suggestedName: String? = null,
    ) {
        val missing: List<FileIssue> get() = issues.filter { it.missing }
        val mismatched: List<FileIssue> get() = issues.filter { !it.missing }
        val severity: Severity
            get() = when (status) {
                Status.OK -> Severity.OK
                Status.WRONG_SET, Status.NEEDS_SAMPLES, Status.RENAME_SUGGESTED -> Severity.WARN
                Status.MISSING_FILES, Status.NEEDS_PARENT, Status.NEEDS_BIOS, Status.CHD_UNSUPPORTED, Status.NOT_IN_DAT -> Severity.ERROR
            }
    }

    /**
     * Result of [resolve]: which core's DAT the zip belongs to ([coreId] null = none) and that core's [report].
     * For RENAME_SUGGESTED the report was produced as if the zip already had `report.suggestedName`.
     */
    data class Resolution(val coreId: String?, val report: Report) {
        val status: Status get() = report.status
    }

    private class Entry(val crc: String, val size: Long)

    /**
     * @param sibling resolves "<name>.zip" in the game's folder (case-insensitive lookups can be plugged in).
     * @param samplesDir `<system>/<core>/samples`, or null to skip the sample check.
     * @param chdSupported false (MAME 2003-Plus) turns any CHD game into CHD_UNSUPPORTED; true (MAME 2010) checks
     *   the ROM files only and leaves `disks` for the UI to mention.
     * @param asName check the zip as if it were named `<asName>.zip` (CRC identification / rename preview).
     */
    fun check(
        db: Db,
        zip: File,
        samplesDir: File? = null,
        sibling: (String) -> File = { File(zip.parentFile ?: File("."), it) },
        chdSupported: Boolean = false,
        asName: String? = null,
    ): Report {
        val shortName = (asName ?: zip.nameWithoutExtension).lowercase()
        val game = db[shortName] ?: return Report(shortName, Status.NOT_IN_DAT, null)

        // romof chain: game → parent → BIOS
        val chain = ArrayList<Game>()
        var cur: Game? = game
        while (cur != null && chain.none { it.name == cur!!.name }) {
            chain.add(cur)
            cur = cur.romof.takeIf { it.isNotEmpty() }?.let { db[it] }
        }
        val parentZip = game.cloneof.ifEmpty { game.romof.takeIf { it.isNotEmpty() && it != game.bios } }
        val biosZip = game.bios.ifEmpty { null }
        val zipFiles = HashMap<String, File>()
        for (g in chain) zipFiles[g.name] = if (g === game) zip else sibling("${g.name}.zip")
        if (biosZip != null && biosZip !in zipFiles) zipFiles[biosZip] = sibling("$biosZip.zip")
        val present = zipFiles.mapValues { it.value.isFile }
        val sampleZip = game.sampleof.ifEmpty { null }
        val samplesPresent = sampleZip != null && samplesDir != null && File(samplesDir, "$sampleZip.zip").isFile

        fun base(status: Status, issues: List<FileIssue> = emptyList(), needed: String? = null) = Report(
            shortName = game.name, status = status, game = game, issues = issues,
            parentZip = parentZip, parentPresent = parentZip != null && present[parentZip] == true,
            biosZip = biosZip, biosPresent = biosZip != null && present[biosZip] == true,
            sampleZip = sampleZip, samplesPresent = samplesPresent, disks = game.disks, neededZip = needed,
        )
        if (game.disks > 0 && !chdSupported) return base(Status.CHD_UNSUPPORTED)

        // Entries of every present zip in the chain, in search order.
        val contents: List<Pair<String, Map<String, Entry>>> = chain.mapNotNull { g ->
            val f = zipFiles[g.name] ?: return@mapNotNull null
            if (!f.isFile) return@mapNotNull null
            g.name to readEntries(f)
        }
        if (contents.isEmpty() || contents.first().first != game.name) {
            // Unreadable / corrupt game zip: everything is missing.
            return base(Status.MISSING_FILES, game.roms.filter { it.bios == null }.map { FileIssue(it.name, it.crc, it.size, null, ownerOf(game, chain, it)) })
        }

        fun lookup(rom: Rom): Entry? { // exact match by CRC anywhere in the chain
            for ((_, entries) in contents) {
                entries.values.firstOrNull { it.crc == rom.crc && (rom.size == 0L || it.size == rom.size) }?.let { return it }
            }
            return null
        }
        fun byName(rom: Rom): Entry? {
            val names = if (rom.merged && rom.mergeName != rom.name) listOf(rom.name, rom.mergeName) else listOf(rom.name)
            for ((_, entries) in contents) for (n in names) entries[n.lowercase()]?.let { return it }
            return null
        }

        val issues = ArrayList<FileIssue>()
        for (rom in game.roms) {
            if (rom.bios != null) continue
            if (lookup(rom) != null) continue
            issues.add(FileIssue(rom.name, rom.crc, rom.size, byName(rom)?.crc, ownerOf(game, chain, rom)))
        }
        val biosRoms = game.roms.filter { it.bios != null }
        if (biosRoms.isNotEmpty() && biosRoms.none { lookup(it) != null }) {
            val first = biosRoms.first()
            issues.add(FileIssue(first.name, first.crc, first.size, byName(first)?.crc, ownerOf(game, chain, first)))
        }

        if (issues.isEmpty()) {
            return base(if (game.needsSamples && !samplesPresent) Status.NEEDS_SAMPLES else Status.OK)
        }
        val missing = issues.filter { it.missing }
        if (missing.isEmpty()) return base(Status.WRONG_SET, issues)
        val absentOwners = missing.map { it.owner }.distinct().filter { it != game.name && present[it] != true }
        return when {
            biosZip != null && biosZip in absentOwners -> base(Status.NEEDS_BIOS, issues, biosZip)
            absentOwners.isNotEmpty() -> base(Status.NEEDS_PARENT, issues, absentOwners.first())
            else -> base(Status.MISSING_FILES, issues)
        }
    }

    /**
     * Routes [zip] to the first DB (in [dbs] order, e.g. MAME 2003-Plus → MAME 2010) that lists its short name
     * and checks it there. When none does, identifies the set by entry CRCs in the same order and returns
     * RENAME_SUGGESTED (the report is the check under the suggested name, so missing files are still listed).
     * Otherwise NOT_IN_DAT with `coreId == null`.
     *
     * @param samplesDir per-core samples folder (null = don't judge samples)
     * @param chdSupported per-core CHD capability (see [check])
     */
    fun resolve(
        dbs: List<Pair<String, Db>>,
        zip: File,
        samplesDir: (String) -> File? = { null },
        chdSupported: (String) -> Boolean = { false },
        sibling: (String) -> File = { File(zip.parentFile ?: File("."), it) },
    ): Resolution {
        val shortName = zip.nameWithoutExtension.lowercase()
        for ((id, db) in dbs) {
            if (db[shortName] == null) continue
            return Resolution(id, check(db, zip, samplesDir(id), sibling, chdSupported(id)))
        }
        val crcs = readEntries(zip).values.mapTo(HashSet()) { it.crc }
        if (crcs.isNotEmpty()) {
            for ((id, db) in dbs) {
                val game = db.identify(crcs) ?: continue
                val r = check(db, zip, samplesDir(id), sibling, chdSupported(id), asName = game.name)
                return Resolution(id, r.copy(shortName = shortName, status = Status.RENAME_SUGGESTED, suggestedName = game.name))
            }
        }
        return Resolution(null, Report(shortName, Status.NOT_IN_DAT, null))
    }

    /** Which set in the chain actually ships [rom] (follows merge names up to the first non-merged definition). */
    private fun ownerOf(game: Game, chain: List<Game>, rom: Rom): String {
        if (!rom.merged) return game.name
        var name = rom.mergeName
        for (anc in chain.drop(1)) {
            val target = anc.roms.firstOrNull { it.name.equals(name, ignoreCase = true) } ?: continue
            if (!target.merged) return anc.name
            name = target.mergeName
        }
        return game.bios.ifEmpty { game.romof.ifEmpty { game.name } }
    }

    /** lowercase entry name → CRC/size from the central directory (nothing is inflated). */
    private fun readEntries(file: File): Map<String, Entry> = runCatching {
        ZipFile(file).use { zf ->
            val map = HashMap<String, Entry>()
            for (e in zf.entries()) {
                if (e.isDirectory) continue
                val crc = e.crc
                if (crc < 0) continue
                map[e.name.substringAfterLast('/').lowercase()] = Entry(String.format("%08x", crc), e.size)
            }
            map
        }
    }.getOrDefault(emptyMap())
}
